mapper.update:
UPDATE assignment SET title=#{title}, description=#{description}, class_id=#{classId},
due_date=#{dueDate}, max_score=#{maxScore}, rubric=#{rubric}, status=#{status}, update_time=NOW()
WHERE id=#{id}

mapper.select:
SELECT s.*, u.username AS student_name FROM assignment_submission s
LEFT JOIN user u ON s.student_id=u.id
WHERE s.assignment_id=#{assignmentId} AND s.student_id=#{studentId}
